package net.civeira.phylax.integrationtest.features.oauth.alt;

import java.time.Instant;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

import io.quarkus.arc.profile.IfBuildProfile;
import jakarta.annotation.Priority;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.inject.Alternative;
import net.civeira.phylax.features.oauth.tokensecurity.domain.gateway.TokenRevocationGateway;

/**
 * In-memory test alternative for {@link TokenRevocationGateway}.
 *
 * Tracks revoked JTIs in a {@link ConcurrentHashMap}. Ignores expiry and tenant for lookup
 * simplicity — uniqueness is guaranteed by the UUID JTI. Call {@link #clear()} in
 * {@code @BeforeEach} to reset state between tests.
 */
@IfBuildProfile("test")
@Alternative
@Priority(1)
@ApplicationScoped
public class FixedTokenRevocationGateway implements TokenRevocationGateway {

  private final Set<String> revoked = ConcurrentHashMap.newKeySet();

  public void clear() {
    revoked.clear();
  }

  @Override
  public void revokeJti(String jti, String tenantId, String tokenType, Instant expiresAt) {
    revoked.add(jti);
  }

  @Override
  public boolean isRevoked(String jti, String tenantId) {
    return revoked.contains(jti);
  }

  @Override
  public void cleanup() {
    // no-op in tests
  }

  @Override
  public void revokeAllForUser(String username, String clientId, String tenantId) {
    // no-op in tests — theft detection side-effect; individual JTI revocation covers rotation tests
  }

  @Override
  public void revokeAllForSession(String sessionId, String tenantId) {
    // no-op in tests — session revocation tracked via session store; JTI checks not needed
  }
}
